    cb = [-1] + sep_cols + [w]

    result = []
    for r0, r1 in zip(rb, rb[1:]):
        out_row = []
        for c0, c1 in zip(cb, cb[1:]):
            positions = {}
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    v = grid[r][c]
                    if v != 0:
                        positions.setdefault(v, []).append((r, c))

            found = False
            for coords in positions.values():
                for i, (r, c) in enumerate(coords):
                    if any(r == rr or c == cc for rr, cc in coords[i + 1:]):
                        found = True
                        break
                if found:
                    break
            out_row.append(int(found))
        result.append(out_row)
    return result
